{
    if (stressGc)
    {
        // Evita a alocação contínua de strings temporárias e arrays no heap a cada frame
    }

    if (stressCpu)
    {
        for (int k = 0; k < cpuScansPerFrame; k++)
        {
            var allObjects = GameObject.FindObjectsOfType<GameObject>();
            GC.KeepAlive(allObjects);
        }
    }

    if (stressDraw && testPrefab != null)
    {
        int n = Mathf.Max(1, cubesPerFrame);
        for (int i = 0; i < n; i++) SpawnOne();
    }
}",
      "explicacao_didatica": "O Garbage Collector (coletor de lixo, ou GC) é um sistema automático do Unity e do C# encarregado de liberar espaço na memória que não está mais sendo utilizado. Quando concatenamos textos (strings) usando o operador '+' ou instanciamos novos arrays repetidamente dentro do método Update (que roda a cada quadro), o jogo reserva novos blocos de memória no 'heap' (área de alocação dinâmica). Como strings são imutáveis, cada junção cria uma string totalmente nova e descarta a anterior. Quando a memória acumulada fica cheia, o GC pausa a execução do jogo para varrer e recolher o lixo gerado, provocando engasgos (o gc_collect_ms de 22.75 ms). Para evitar isso, deve-se eliminar a criação de objetos temporários nos métodos executados a cada frame."
    }
  ],
